corrected_code:
const express = require('express');
const { verifyTurborepoToken } = require('../auth/turbo');
const { ArtifactStorage } = require('../storage/artifacts');

const app = express();

app.get('/v2/artifacts/:hash', verifyTurborepoToken, async (req, res) => {
  const { hash } = req.params;
  const effectiveTeamId = req.query.teamId || req.user.defaultTeamId;

  // Ensure caller has access to the requested team workspace
  if (!req.user.authorizedTeams?.includes(effectiveTeamId)) {
    return res.status(403).json({ error: 'Access denied to team cache space' });
  }

  const artifact = await ArtifactStorage.findOne({
    where: { hash, teamId: effectiveTeamId }
  });

  if (!artifact) {
    return res.status(404).json({ error: 'Artifact not found in team cache' });
  }

  res.setHeader('Content-Type', 'application/octet-stream');
  res.setHeader('x-artifact-tag', artifact.tag);
  artifact.createReadStream().pipe(res);
});

module.exports = app;
